 if(hit||ball.mesh.position.y<.15||ball.life<=0){if(!hit)quests.noise(ball.mesh.position.x,ball.mesh.position.z);emit(ball.mesh.position.x,.2,ball.mesh.position.z,9,0xfaffff,1.5);ball.life=0;ball.mesh.visible=false;}
