 if(zone!==lastZone){lastZone=zone;if(zone){zoneTime=2.8;$('locationLabel').textContent=zone.toUpperCase();$('locationLabel').classList.add('visible');}}
 const prompt=interaction();lastInteract=prompt;$('interactPrompt').classList.toggle('hidden',!prompt||state.phase!=='playing');if(prompt){$('interactLabel').textContent=prompt.text;const l=prompt.type==='part'?'TA':prompt.type==='home'?'BYGG':'';setIcon('touchAction','a'+l,()=>l||icon('dot',22));}else setIcon('touchAction','a',()=>icon('dot',22));
