function drawMap(){let c=$('mapCanvas'),ctx=c.getContext('2d'),w=c.width,h=c.height,s=w/245,ox=w/2,oz=h/2;ctx.clearRect(0,0,w,h);ctx.fillStyle='#1e5065';ctx.fillRect(0,0,w,h);ctx.beginPath();world.boundary.forEach((p,i)=>i?ctx.lineTo(ox+p.x*s,oz+p.y*s):ctx.moveTo(ox+p.x*s,oz+p.y*s));ctx.closePath();ctx.fillStyle='#d0e7e7';ctx.fill();ctx.strokeStyle='#82c8d9';ctx.lineWidth=2;ctx.stroke();ctx.fillStyle='#8bcedc';ctx.beginPath();ctx.ellipse(ox+15*s,oz+57*s,19*s,11*s,0,0,Math.PI*2);ctx.fill();const dot=(x,z,r,color)=>{ctx.beginPath();ctx.arc(ox+x*s,oz+z*s,r,0,Math.PI*2);ctx.fillStyle=color;ctx.fill();};for(const p of world.pickups)if(state.parts[p.index]===0){dot(p.group.position.x,p.group.position.z,4.2,'#d59332');ctx.fillStyle='#f8e19d';ctx.fillRect(ox+p.group.position.x*s-1,oz+p.group.position.z*s-1,2,2);}for(const sh of SHELTERS)dot(sh.x,sh.z,2.4,'#de825b');const goal=nearestTarget();ctx.beginPath();ctx.arc(ox+goal.x*s,oz+goal.z*s,7,0,Math.PI*2);ctx.strokeStyle='#e49a31';ctx.stroke();dot(SHOP.x,SHOP.z,3.6,'#3c918b');dot(0,0,6,'#264b5c');ctx.fillStyle='#e9f9f4';ctx.font='bold 10px sans-serif';ctx.textAlign='center';ctx.fillText('⌂',ox,oz+4);dot(world.rival.group.position.x,world.rival.group.position.z,3.3,'#8e6abd');for(const b of world.bears)dot(b.x,b.z,2.8,b.alert?'#ec704f':'#7b969e');if(world.supply.visible)dot(world.supply.position.x,world.supply.position.z,3.6,'#eeb442');dot(player.x,player.z,5,'#fa784c');ctx.strokeStyle='#fff';ctx.lineWidth=1.6;ctx.stroke();ctx.beginPath();ctx.moveTo(ox+player.x*s,oz+player.z*s);ctx.lineTo(ox+(player.x+Math.sin(player.angle)*4)*s,oz+(player.z+Math.cos(player.angle)*4)*s);ctx.strokeStyle='#fa784c';ctx.lineWidth=2;ctx.stroke();}
function updateEffects(dt){for(let i=0;i<effects.length;i++){const e=effects[i];e.life=Math.max(0,e.life-dt);if(e.life>0){if(e.kind!=='foot'){e.vy-=5*dt;e.x+=e.vx*dt;e.y+=e.vy*dt;e.z+=e.vz*dt;if(e.y<.05){e.y=.05;e.vy*=.15;e.vx*=.8;e.vz*=.8;}}e.size=e.base*Math.min(1,e.life*3);effectMatrix.position.set(e.x,e.y,e.z);if(e.kind==='foot'){effectMatrix.scale.set(e.size,.011,e.size*1.7);effectMatrix.rotation.set(0,player.angle,0);}else{effectMatrix.scale.setScalar(e.size);effectMatrix.rotation.set(e.life*2,e.life*3,0);}effectColor.set(e.color);world.particles.setColorAt(i,effectColor);}else{effectMatrix.position.set(0,-100,0);effectMatrix.scale.setScalar(0);}effectMatrix.updateMatrix();world.particles.setMatrixAt(i,effectMatrix.matrix);}world.particles.instanceMatrix.needsUpdate=true;if(world.particles.instanceColor)world.particles.instanceColor.needsUpdate=true;}
function animateWorld(dt){const active=state.phase==='playing'||state.phase==='menu'||state.phase==='launching'||state.phase==='won'||state.phase==='lost';const at=active?time:state.time;world.waterUniforms.time.value=at;world.floes.forEach((f,i)=>{f.position.y=-4.2+Math.sin(at*.6+i)*.12;});for(const {f} of world.flags){f.rotation.y=Math.sin(at*3+f.parent.position.x)*.16;f.scale.x=1+Math.sin(at*4)*.025;}world.flames.forEach((f,i)=>{f.scale.y=(i?1:1.3)*(.87+Math.sin(at*13+i)*.1);f.rotation.y=at;});world.fireLight.intensity=11+Math.sin(at*17);world.beacon.material.emissiveIntensity=1+Math.sin(at*2)*.6;world.piff.animate(at,0,.2);for(const a of world.animals){if(a.type==='penguin'){const p=a.model.group.position,tx=a.home.x+Math.sin(at*.22+a.phase)*1.7,tz=a.home.z+Math.cos(at*.19+a.phase)*1.6,dx=tx-p.x,dz=tz-p.z;p.x+=dx*Math.min(1,dt);p.z+=dz*Math.min(1,dt);a.model.group.rotation.y=Math.atan2(dx,dz);a.model.animate(at,.35);}else a.model.animate(at,0);}
 if(state.phase==='menu'){world.explorer.group.position.set(1,0,8);world.explorer.group.rotation.y=-.4;world.explorer.animate(time,0);world.rival.animate(time,.15);world.bears.forEach(b=>b.model.animate(time,0));world.pickups.forEach((p,i)=>{p.model.rotation.y=time*.65+i;p.model.position.y=(p.thief?1.8:p.lock?1.7:.55)+Math.sin(time*1.8+i)*.13;if(p.thief)p.thief.animate(time,0);});for(const c of world.coins){c.group.rotation.y=time+c.phase;c.group.position.y=.8+Math.sin(time*2+c.phase)*.13;}}
 const storm=currentEvent==='storm'&&state.phase!=='menu',aurora=currentEvent==='aurora';let snow=world.snowPos;const n=storm?850:240;world.snowfall.geometry.setDrawRange(0,n);for(let i=0;i<n;i++){snow[i*3]+=(storm?-11:-.7)*dt;snow[i*3+1]-=(storm?7:1.6)*dt;snow[i*3+2]+=(storm?3:.25)*dt;if(snow[i*3+1]<0)snow[i*3+1]=26;if(snow[i*3]<player.x-65)snow[i*3]=player.x+65;if(snow[i*3]>player.x+65)snow[i*3]=player.x-65;if(snow[i*3+2]<player.z-65)snow[i*3+2]=player.z+65;if(snow[i*3+2]>player.z+65)snow[i*3+2]=player.z-65;}world.snowfall.geometry.attributes.position.needsUpdate=true;world.snowMat.size=storm?.17:.095;world.snowMat.opacity=storm?.75:.5;$('whiteout').style.opacity=storm?'.13':'0';world.auroraMat.uniforms.time.value=time;world.auroraMat.uniforms.strength.value+=((aurora?.5:0)-world.auroraMat.uniforms.strength.value)*Math.min(1,dt*.3);world.auroraMat.uniforms.strength.value=Math.min(.5,Math.max(0,world.auroraMat.uniforms.strength.value));sound.update(state.time,storm,state.phase==='playing'||state.phase==='launching');updateRigs();}
function resize(){renderer.setSize(innerWidth,innerHeight);updateCamera(1,true);}
function updateCamera(dt,instant=false){let target=new THREE.Vector3(player.x,0,player.z),z=targetZoom;if(state.phase==='menu'){target.set(isTouch?0:7,0,isTouch?3:-5);z=isTouch?57:64;}if(state.phase==='launching'||state.phase==='won'){target.set(0,Math.min(60,world.rocket.group.position.y*.72),0);z=29;}zoom+=(z-zoom)*(1-Math.exp(-dt*4));if(instant)zoom=z;cameraTarget.lerp(target,instant?1:1-Math.exp(-dt*5));const aspect=innerWidth/innerHeight;camera.left=-zoom*aspect;camera.right=zoom*aspect;camera.top=zoom;camera.bottom=-zoom;camera.updateProjectionMatrix();camera.position.set(cameraTarget.x+44,cameraTarget.y+55,cameraTarget.z+44);camera.lookAt(cameraTarget);world.sun.position.set(cameraTarget.x-32,64,cameraTarget.z+36);world.sun.target.position.set(cameraTarget.x,0,cameraTarget.z);const shadowSpan=state.phase==='menu'?112:50;if(world.sun.shadow.camera.right!==shadowSpan){Object.assign(world.sun.shadow.camera,{left:-shadowSpan,right:shadowSpan,top:shadowSpan,bottom:-shadowSpan});world.sun.shadow.camera.updateProjectionMatrix();}if(shake>0){camera.position.x+=(Math.random()-.5)*shake;camera.position.z+=(Math.random()-.5)*shake;}if(state.phase==='playing'){let p=nearestTarget();projected.set(p.x,3.2,p.z).project(camera);let x=(projected.x*.5+.5)*innerWidth,y=(-projected.y*.5+.5)*innerHeight;const outside=x<40||x>innerWidth-40||y<65||y>innerHeight-55;x=Math.max(28,Math.min(innerWidth-28,x));y=Math.max(70,Math.min(innerHeight-75,y));$('targetMarker').style.left=x+'px';$('targetMarker').style.top=y+'px';{const t=p.type==='home'?'home':p.type==='shelter'?'flame':'diamond';setIcon('targetIcon',t,()=>icon(t,22));}$('targetDistance').textContent=Math.round(dist(player,p))+' m';$('targetMarker').style.opacity=dist(player,p)<3?'0':'1';}}
function frame(now){const dt=Math.min((now-lastFrame)/1000,.05);lastFrame=now;time+=dt;accumulator+=dt;while(accumulator>=1/60){tick(1/60);accumulator-=1/60;}animateWorld(dt);if(state.phase==='playing'||state.phase==='launching'||state.phase==='lost'||state.phase==='won')updateEffects(dt);shake=Math.max(0,shake-dt*.8);damage=Math.max(0,damage-dt);$('damage').style.opacity=damage*.55;updateCamera(dt);uiTime+=dt;if(uiTime>.1){uiTime=0;updateHUD();}toastTime-=dt;if(toastTime<=0)$('toast').classList.remove('visible');pickupTime-=dt;if(pickupTime<=0)$('pickupText').classList.remove('visible');zoneTime-=dt;if(zoneTime<=0)$('locationLabel').classList.remove('visible');renderer.render(world.scene,camera);requestAnimationFrame(frame);}

$('start').addEventListener('click',start);$('restart').addEventListener('click',start);$('restartPause').addEventListener('click',start);$('returnMenu').addEventListener('click',()=>{currentEvent=null;world.rocket.group.position.y=.34;world.rocket.flame.visible=false;world.explorer.group.visible=true;world.novaRocket.group.position.y=.34;world.novaRocket.flame.visible=false;setPhase('menu');updateBestText();});$('pause').addEventListener('click',()=>{if(state.phase==='playing'){setPhase('paused');$('resume').focus();}});$('resume').addEventListener('click',()=>{sound.boot();setPhase('playing');});$('sound').addEventListener('click',()=>{sound.boot();sound.setEnabled(!sound.enabled);$('sound').innerHTML=icon(sound.enabled?'soundOn':'soundOff');$('sound').style.opacity=sound.enabled?'1':'.5';$('sound').setAttribute('aria-label',sound.enabled?'Stäng av ljud':'Slå på ljud');});$('mapToggle').addEventListener('click',()=>{$('minimap').classList.toggle('open');drawMap();});$('rocketBoard').addEventListener('click',e=>{if(state.phase!=='playing')return;const slot=e.target.closest('.part-slot');if(slot){const i=Number(slot.id.slice(4));if(state.parts[i]===0){state.quest.activePart=i;updateHUD();sound.play('switch');}else if(Math.hypot(player.x,player.z)<5)openWorkshop();else notify('Tillbaka till raketen.');}else if(Math.hypot(player.x,player.z)<5)openWorkshop();});$('rocketBoard').addEventListener('keydown',e=>{if(['Enter','Space'].includes(e.code)&&e.target.classList.contains('part-slot')){e.preventDefault();e.stopPropagation();e.target.click();}});$('install').addEventListener('click',install);$('launch').addEventListener('click',launch);for(const id of ['closeWorkshop','leaveWorkshop','closeShop','leaveShop'])$(id).addEventListener('click',()=>setPhase('playing'));
$('touchDodge').innerHTML=icon('zap',22);
function boardId(){return 'strandad-antarktis:'+(mode==='race'?'race':'adventure');}
function ludvigBoard(el,board){try{const ui=window.Ludvig&&window.Ludvig.ui;if(!ui||!el)return;el.textContent='';ui.board(el,{board,limit:5});}catch{}}
function ludvigOpen(board){try{const ui=window.Ludvig&&window.Ludvig.ui;if(ui)ui.open({board});}catch{}}
if(window.Ludvig&&window.Ludvig.ui)$('menuBoard').hidden=false;
$('menuBoard').addEventListener('click',e=>{e.currentTarget.blur();ludvigOpen(boardId());});
$('menuBoard').addEventListener('keydown',e=>{if(e.code==='Enter'||e.code==='Space')e.stopPropagation();});
addEventListener('ludvig:score',()=>{if(state.phase==='won'||state.phase==='lost')ludvigBoard($('endBoard'),boardId());});
document.querySelectorAll('[data-mode]').forEach(b=>b.addEventListener('click',()=>{mode=b.dataset.mode;document.querySelectorAll('[data-mode]').forEach(c=>{c.classList.toggle('selected',c===b);c.setAttribute('aria-pressed',String(c===b));});updateBestText();}));
addEventListener('keydown',e=>{if(['Space','ArrowUp','ArrowDown','ArrowLeft','ArrowRight'].includes(e.code))e.preventDefault();if(e.repeat){if(state.phase==='playing')keys.add(e.code);return;}if(e.code==='Enter'&&state.phase==='menu'){e.preventDefault();start();return;}if(e.code==='KeyR'&&(state.phase==='won'||state.phase==='lost')){start();return;}if(e.code==='Escape'){if(state.phase==='playing'){setPhase('paused');$('resume').focus();}else if(['paused','workshop','shop'].includes(state.phase))setPhase('playing');return;}if(state.phase!=='playing')return;keys.add(e.code);if(e.code==='KeyE'){e.preventDefault();interact();}if(e.code==='Space')throwSnow();if(e.code==='KeyC')dodge();if(e.code==='KeyQ'){$('minimap').classList.toggle('open');drawMap();}if(e.code==='KeyM')$('sound').click();if(e.code==='KeyB'){if(Math.hypot(player.x,player.z)<5)openWorkshop();else notify('Bygg vid raketen. Du kan bära två delar åt gången.');}});
addEventListener('keyup',e=>keys.delete(e.code));addEventListener('resize',resize);document.addEventListener('visibilitychange',()=>{if(document.hidden&&state.phase==='playing')setPhase('paused');lastFrame=performance.now();accumulator=0;});addEventListener('blur',()=>{keys.clear();touchRunning=false;touchInteracting=false;touchVector={x:0,y:0};resetStick();});
function screenPoint(clientX,clientY){mouse.set(clientX/innerWidth*2-1,-clientY/innerHeight*2+1);raycaster.setFromCamera(mouse,camera);let result=raycaster.ray.intersectPlane(ground,point);return result?{x:result.x,z:result.z}:null;}
canvas.addEventListener('pointermove',e=>{if(e.pointerType==='touch')return;pointerWorld=screenPoint(e.clientX,e.clientY);pointerMovedAt=time;});canvas.addEventListener('pointerdown',e=>{if(state.phase!=='playing'||e.button!==0)return;let p=screenPoint(e.clientX,e.clientY);if(p&&onIsland(p.x,p.z)){moveTarget=p;canvas.style.cursor='crosshair';}});canvas.addEventListener('contextmenu',e=>{e.preventDefault();pointerWorld=screenPoint(e.clientX,e.clientY);throwSnow(true);});canvas.addEventListener('wheel',e=>{if(state.phase!=='playing')return;e.preventDefault();targetZoom=Math.max(15,Math.min(40,targetZoom+e.deltaY*.018));},{passive:false});
let stickId=null;function resetStick(){stickId=null;$('stick').style.transform='translate(0px,0px)';}
function stickMove(e){if(e.pointerId!==stickId)return;let r=$('joystick').getBoundingClientRect(),dx=e.clientX-r.left-r.width/2,dy=e.clientY-r.top-r.height/2,d=Math.hypot(dx,dy),lim=r.width*.33;if(d>lim){dx=dx/d*lim;dy=dy/d*lim;}touchVector={x:dx/lim,y:dy/lim};$('stick').style.transform=`translate(${dx}px,${dy}px)`;}
$('joystick').addEventListener('pointerdown',e=>{e.preventDefault();if(state.phase!=='playing')return;stickId=e.pointerId;$('joystick').setPointerCapture(e.pointerId);stickMove(e);});$('joystick').addEventListener('pointermove',stickMove);for(const ev of ['pointerup','pointercancel','lostpointercapture'])$('joystick').addEventListener(ev,e=>{if(e.pointerId===stickId){touchVector={x:0,y:0};resetStick();}});$('touchRun').addEventListener('pointerdown',e=>{e.preventDefault();touchRunning=true;$('touchRun').setPointerCapture(e.pointerId);});for(const ev of ['pointerup','pointercancel','lostpointercapture'])$('touchRun').addEventListener(ev,()=>touchRunning=false);$('touchAction').addEventListener('pointerdown',e=>{e.preventDefault();touchInteracting=true;$('touchAction').setPointerCapture(e.pointerId);interact();});for(const ev of ['pointerup','pointercancel','lostpointercapture'])$('touchAction').addEventListener(ev,()=>touchInteracting=false);$('touchDodge').addEventListener('pointerdown',e=>{e.preventDefault();dodge();});$('touchSnow').addEventListener('pointerdown',e=>{e.preventDefault();throwSnow();});
